INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(15043, 1504, 'listening', 'Listening Part 3: Presentation about refrigeration', '<div class="ielts-reading-container">
<h2 class="ielts-reading-question-section-heading">
                                            Questions 21-24                                                                                                                                                
                                                                                                                                    </h2>
                                                                                    
                                                                                <div class="ielts-reading-question-section-content">
                                            <p>Choose the correct letter, <strong>A</strong>, <strong>B</strong> or <strong>C</strong>.</p>
<p class="ielts-listening-transcript-subhead"><strong><strong>Presentation about refrigeration</strong></strong></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="21"><div class="ielts-q-header"><strong class="ielts-q-badge">21</strong><span class="ielts-q-title"><span>What did Annie discover from reading about icehouses?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="21" name="question_21" value="A"><span class="ielts-radio-text"><strong>A</strong> why they were first created</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="21" name="question_21" value="B"><span class="ielts-radio-text"><strong>B</strong> how the ice was kept frozen</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="21" name="question_21" value="C"><span class="ielts-radio-text"><strong>C</strong> where they were located</span></label></div></div><div class="ielts-standalone-q" data-qnum="22"><div class="ielts-q-header"><strong class="ielts-q-badge">22</strong><span class="ielts-q-title"><span>What point does Annie make about refrigeration in ancient Rome?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="22" name="question_22" value="A"><span class="ielts-radio-text"><strong>A</strong> It became a commercial business.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="22" name="question_22" value="B"><span class="ielts-radio-text"><strong>B</strong> It used snow from nearby.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="22" name="question_22" value="C"><span class="ielts-radio-text"><strong>C</strong> It took a long time to become popular.</span></label></div></div><div class="ielts-standalone-q" data-qnum="23"><div class="ielts-q-header"><strong class="ielts-q-badge">23</strong><span class="ielts-q-title"><span>In connection with modern refrigerator, both Annie and Jack are worried about</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="23" name="question_23" value="A"><span class="ielts-radio-text"><strong>A</strong> the complexity of the technology.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="23" name="question_23" value="B"><span class="ielts-radio-text"><strong>B</strong> the fact that some are disposed of irresponsibly.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="23" name="question_23" value="C"><span class="ielts-radio-text"><strong>C</strong> the large number that quickly break down.</span></label></div></div><div class="ielts-standalone-q" data-qnum="24"><div class="ielts-q-header"><strong class="ielts-q-badge">24</strong><span class="ielts-q-title"><span>What do Jack and Annie agree regarding domestic fridges?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="24" name="question_24" value="A"><span class="ielts-radio-text"><strong>A</strong> They are generally good value for money.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="24" name="question_24" value="B"><span class="ielts-radio-text"><strong>B</strong> There are plenty of useful variations.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="24" name="question_24" value="C"><span class="ielts-radio-text"><strong>C</strong> They are more useful than other domestic appliances.</span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 25-30                                                                                                                                                
                                                                                                                                    </h2>
                                                                                    
                                                                                <div class="ielts-reading-question-section-content">
                                            <p>Who is going to do research into each topic?</p>
<p>Write the correct letter, <strong>A</strong>, <strong>B</strong> or <strong>C</strong>, next to Questions.</p>
<p><strong>People</strong></p>
<p><strong>Topics</strong></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                                <div class="matching-dnd-questions"><div class="ielts-listening-question-item"> • <span>the goods that are refrigerated</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">25</strong><select data-qnum="25" name="question_25" class="ielts-inline-select"><option value="">[ 25 ] Tanlang...</option><option value="A. Annie">A. Annie</option><option value="B. Jack">B. Jack</option><option value="C. both Annie and Jack">C. both Annie and Jack</option></select></span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="ielts-listening-question-item"> • <span>the effects on health</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">26</strong><select data-qnum="26" name="question_26" class="ielts-inline-select"><option value="">[ 26 ] Tanlang...</option><option value="A. Annie">A. Annie</option><option value="B. Jack">B. Jack</option><option value="C. both Annie and Jack">C. both Annie and Jack</option></select></span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="ielts-listening-question-item"> • <span>the impact on food producers</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">27</strong><select data-qnum="27" name="question_27" class="ielts-inline-select"><option value="">[ 27 ] Tanlang...</option><option value="A. Annie">A. Annie</option><option value="B. Jack">B. Jack</option><option value="C. both Annie and Jack">C. both Annie and Jack</option></select></span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="ielts-listening-question-item"> • <span>the impact on cities</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">28</strong><select data-qnum="28" name="question_28" class="ielts-inline-select"><option value="">[ 28 ] Tanlang...</option><option value="A. Annie">A. Annie</option><option value="B. Jack">B. Jack</option><option value="C. both Annie and Jack">C. both Annie and Jack</option></select></span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="ielts-listening-question-item"> • <span>refrigerated transport</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">29</strong><select data-qnum="29" name="question_29" class="ielts-inline-select"><option value="">[ 29 ] Tanlang...</option><option value="A. Annie">A. Annie</option><option value="B. Jack">B. Jack</option><option value="C. both Annie and Jack">C. both Annie and Jack</option></select></span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="ielts-listening-question-item"> • <span>domestic fridges</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">30</strong><select data-qnum="30" name="question_30" class="ielts-inline-select"><option value="">[ 30 ] Tanlang...</option><option value="A. Annie">A. Annie</option><option value="B. Jack">B. Jack</option><option value="C. both Annie and Jack">C. both Annie and Jack</option></select></span></div></div>                                                                        <div class="options-dnd-panel dnd-panel dnd-panel--matching" data-dnd-group="13002" data-allow-duplicates="true">
                                                                            <div class="dnd-panel-instruction">Drag and drop an option to fill in each blank.</div>
                                                                            <div class="dnd-cards-container">
                                                                                                                                                                    <div class="dnd-card" draggable="true" data-value="A" data-text="A. Annie">
                                                                                        <span class="dnd-label">A.</span>
                                                                                        <span class="dnd-text">Annie</span>
                                                                                    </div>
                                                                                                                                                                    <div class="dnd-card" draggable="true" data-value="B" data-text="B. Jack">
                                                                                        <span class="dnd-label">B.</span>
                                                                                        <span class="dnd-text">Jack</span>
                                                                                    </div>
                                                                                                                                                                    <div class="dnd-card" draggable="true" data-value="C" data-text="C. both Annie and Jack">
                                                                                        <span class="dnd-label">C.</span>
                                                                                        <span class="dnd-text">both Annie and Jack</span>
                                                                                    </div>
                                                                                                                                                            </div>
                                                                        </div>
                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                        </div>
</div>', 'https://ielts-listening-audio.engnovatemedia.com/26109-cambridge-ielts-15-academic-listening-4-audio-3.mp3', 'ANNIE: OK, Jack. Before we plan our presentation about refrigeration, let’s discuss what we’ve discovered so far.
JACK: Fine, Annie. Though I have to admit I haven’t done much research yet.
ANNIE: Nor me. But I found an interesting article about icehouses. I’d been some 18th- and 19th-century ones here in the UK, so I knew they were often built in a shady area or underground, close to lakes that might freeze in the winter. Then blocks of ice could be cut and stored in the icehouse. But I didn’t realise that insulating the blocks with straw or sawdust meant they didn’t melt for months. The ancient Romans had refrigeration, too.
JACK: I didn’t know that.
ANNIE: Yes, pits were dug in the ground, and snow was imported from the mountains – even though they were at quite a distance. The snow was stored in the pits. Ice formed at the bottom of it. Both the ice and the snow were then sold. The ice cost more than the snow and my guess is that only the wealthy members of society could afford it.
JACK: I wouldn’t be surprised. I also came across an article about modern domestic fridges. Several different technologies are used, but they were too complex for me to understand.
ANNIE: You have to wonder what happens when people get rid of old ones.
JACK: You mean because the gases in them are harmful for the environment?
ANNIE: Exactly. At least these are now plenty of organisations that will recycle most of the components safety, but of course some people just dump old fridges in the countryside.
JACK: It’s hard to see how they can be stopped unfortunately. In the UK we get rid of three million a year altogether!
ANNIE: That sounds a lot, especially because fridges hardly ever break down.
JACK: That’s right. In this country we keep domestic fridges for 11 years on average, and a lot last for 20 or more. So if you divide the cost by the number of years you can use a fridge, they’re not expensive, compared with some household appliances.
ANNIE: True. I suppose manufactures encourage people to spend more by making them different colours and designs. I’m sure when my parents bought their first fridge they had hardly any choice!
JACK: Yes, there’s been quite a change.
———————
JACK: Right, let’s make a list of topics to cover in our presentation, and decide who’s going to do more research on them. Then later, we can get together and plan the next step.
ANNIE: OK. How about starting with how useful refrigeration is, and the range of goods that are refrigerated nowadays? Because of course it’s not just food and drinks.
JACK: No, I suppose flowers and medicines are refrigerated, too.
ANNIE: And computers. I could do that, unless you particularly want to.
JACK: No, that’s fine by me. What about the effects of refrigeration on people’s health? After all, some of the chemicals used in the 19th century were pretty harmful, but there have been lots of benefits too, like always have access to fresh food. Do you fancy dealing with that?
ANNIE: I’m no terribly keen, to be honest.
JACK: Nor me. My mind just goes blank when I read anything about chemicals.
ANNIE: Oh, all right then, I’ll do you a favour. But you own me, Jack.
What about the effects on food producers, like farmers in poorer countries being able to export their produce to developed countries? Something for you, maybe?
JACK: I don’t mind. It should be quite interesting.
ANNIE: I think we should also look at how refrigeration has helped whole cities – like Las Vegas, which couldn’t exist without refrigeration because it’s in the middle of a desert.
JACK: Right. I had a quick look at an economics book in the library that’s got a chapter about this sort of thing. I could give you the title, if you want to do this section.
ANNIE: Not particularly, to be honest. I find economics books pretty heavy going, as a rule.
JACK: OK, leave it to me, then.
ANNIE: Thanks. Then there’s transport, and the difference that refrigerated trucks have made. I wouldn’t mind having a go at that.
JACK: Don’t forget trains, too. I read something about milk and butter being transported in refrigerated railroad cars in the USA, right back in the 1840s.
ANNIE: I hadn’t thought of trains. Thanks.
JACK: Shall we have a separate section on domestic fridges? After all, they’re something everyone’s familiar with.
ANNIE: What about splitting it into two? You could investigate 19th- and 20th-century fridges, and I’ll concentrate on what’s available these days, and how manufacturers differentiate their products from those of their competitors.
JACK: OK, that’d suit me.', 3)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, instructions = EXCLUDED.instructions, audio_url = EXCLUDED.audio_url, passage_text = EXCLUDED.passage_text;

